"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["98423"],{96977(e){e.exports=JSON.parse('{"id":"FIN-443","slug":"out-of-the-money","term":"Out-of-the-Money","also_known_as":[],"difficulty":"Intermediate","definition":"An option is out of the money when exercising it immediately would not be profitable: for a call, when the underlying price is below the strike price; for a put, when it is above.","explanation":["Out-of-the-money options have no intrinsic value. Their entire price is time value, reflecting the chance that the underlying asset will move enough before expiry to make them profitable.","For example, if a share trades at 40, a call option with a strike price of 45 is out of the money by 5. A put option with a strike price of 35 is also out of the money by 5.","Out-of-the-money options are cheaper than in-the-money options. This makes them attractive to speculators, because a small investment can produce a large percentage gain if the price moves sharply in the right direction. But they are also more likely to expire worthless, in which case the buyer loses the entire premium.","For instance, a call with a strike of 45 might cost only 0.80 when the share is at 40. If the share rises to 50 by expiry, the option is worth 5, more than six times the premium. If the share stays below 45, the option expires worthless. Out-of-the-money puts are often bought as relatively cheap insurance against a large fall in price."],"note":"","total":1500,"prev":{"slug":"out-of-pocket-maximum","term":"Out-of-Pocket Maximum"},"next":{"slug":"outlier","term":"Outlier"}}')}}]);